CREATE TABLE IF NOT EXISTS duranki_platform_document(id VARCHAR(100) PRIMARY KEY,revision BIGINT UNSIGNED NOT NULL,sha256 CHAR(64) NOT NULL,chunk_count INT NOT NULL,byte_length BIGINT NOT NULL,updated_at VARCHAR(40) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS duranki_platform_chunk(document_id VARCHAR(100) NOT NULL,chunk_index INT NOT NULL,payload LONGBLOB NOT NULL,PRIMARY KEY(document_id,chunk_index),FOREIGN KEY(document_id) REFERENCES duranki_platform_document(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS duranki_platform_migration(id INT PRIMARY KEY,source_sha256 CHAR(64) NOT NULL,counts_json LONGTEXT NOT NULL,migrated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
